  .vorfuehrung-situation-titel { margin: 0 0 4px; font-size: var(--fs-xs); font-weight: var(--fw-bold); letter-spacing: var(--ls-label-klasse); text-transform: var(--label-schreibung); color: var(--ink2); }
  .vorfuehrung-situation { margin: 0 0 var(--space-3); line-height: 1.5; white-space: pre-line; }
  .vorfuehrung-rolle-text { margin: 0 0 var(--space-3); padding: 10px 14px; border-radius: var(--radius-sm); background: var(--vorfuehrung-farbe);
    color: var(--vorfuehrung-auf-farbe); font-weight: var(--fw-bold); font-size: var(--vorfuehrung-fs-rolle); line-height: 1.3; }
  .vorfuehrung-spalte .vorfuehrung-schritt { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--space-2); }
  .vorfuehrung-ueberblick { background: none; border: 0; padding: 0; font: inherit; color: var(--ink2); text-decoration: underline; cursor: pointer; }
  .vorfuehrung-schritte { list-style: none; margin: 0; padding: 0; }
  .vorfuehrung-schritte li { display: flex; gap: 10px; padding: 7px 0; border-bottom: 1px solid var(--line); color: var(--ink2); }
  .vorfuehrung-schritte li.aktiv { color: var(--ink); }
  .vorfuehrung-schritt-nr { flex: none; display: inline-flex; align-items: center; justify-content: center; width: 24px; height: 24px;
    border-radius: 50%; border: 1.5px solid var(--line); font-size: var(--vorfuehrung-fs-schritt); }
  .vorfuehrung-schritte li.aktiv .vorfuehrung-schritt-nr { background: var(--vorfuehrung-farbe); border-color: var(--vorfuehrung-farbe); color: var(--vorfuehrung-auf-farbe); font-weight: var(--fw-bold); }
  .vorfuehrung-spalte .vorfuehrung-karte-titel { font-size: var(--fs-lg, 1.15rem); margin: 0 0 4px; }
  .vorfuehrung-spalte .vorfuehrung-karte-text { margin: 0; white-space: pre-line; }
  .vorfuehrung-spalte--vollmacht .vorfuehrung-leiste .btn:not(.btn-sek) { background: var(--modus-vollmacht); border-color: var(--modus-vollmacht); }
  .vorfuehrung-spalte--vollmacht .vorfuehrung-leiste .btn-sek { color: var(--modus-vollmacht); border-color: var(--modus-vollmacht); }
  #vorfuehrung-wechsel { position: fixed; top: var(--vorfuehrung-oben, var(--vorfuehrung-streifen, 26px)); left: 0; right: 0; bottom: 0; z-index: 360; display: flex;
    align-items: center; justify-content: center; padding: var(--space-5); background: var(--white); }
  .vorfuehrung-wechsel-karte { max-width: 30rem; width: 100%; border: 1px solid var(--line); border-left: var(--akzent-rand-stark) solid var(--vorfuehrung-farbe);
    border-radius: var(--radius-sm); padding: var(--space-5); background: var(--white); box-shadow: var(--vorfuehrung-schatten-wechsel); }
  .vorfuehrung-wechsel-satz { font-size: var(--fs-xl, 1.25rem); font-weight: var(--fw-bold); margin: 0 0 var(--space-3); white-space: pre-line; }
  .vorfuehrung-wechsel.vorfuehrung-spalte--vollmacht .btn { background: var(--modus-vollmacht); border-color: var(--modus-vollmacht); }
  @media (max-width: 1099px) {
    .vorfuehrung-spalte:not(.offen) .vorfuehrung-situation-titel, .vorfuehrung-spalte:not(.offen) .vorfuehrung-situation,
    .vorfuehrung-spalte:not(.offen) .vorfuehrung-schritte li:not(.aktiv) { display: none; }
    .vorfuehrung-spalte:not(.offen) .vorfuehrung-schritte li.aktiv { border-bottom: 0; padding-bottom: 0; }
    .vorfuehrung-spalte.erster:not(.offen) .vorfuehrung-situation { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
      overflow: hidden; margin-bottom: var(--space-2); }
    .vorfuehrung-spalte .vorfuehrung-rolle-text { font-size: var(--vorfuehrung-fs-spalte); padding: 6px 10px; margin-bottom: var(--space-2); }
  }
  @media (min-width: 1100px) {
    html.vorfuehrung-hand body { padding-left: 404px; }
    html.vorfuehrung-hand #modal-rueck { left: 404px; }
    html.vorfuehrung-hand #vorfuehrung-schleife { right: auto; bottom: 0; width: 404px; }
    html.vorfuehrung-hand #vorfuehrung-schleife .vorfuehrung-spalte { height: 100%; max-height: none; display: flex; flex-direction: column;
      border-bottom: 0; border-right: 4px solid var(--vorfuehrung-farbe); box-shadow: none; padding: var(--space-4) var(--space-5); }
    .vorfuehrung-spalte .vorfuehrung-schritte { flex: 1; }
    .vorfuehrung-spalte .vorfuehrung-leiste { position: sticky; bottom: 0; background: var(--white); padding: 10px 0 2px; margin-top: 6px; }
    .vorfuehrung-spalte .vorfuehrung-situation { font-size: var(--vorfuehrung-fs-spalte); }
    .vorfuehrung-spalte .vorfuehrung-schritte li { padding: 5px 0; }
    .vorfuehrung-spalte .vorfuehrung-karte-text { font-size: var(--vorfuehrung-fs-spalte); line-height: 1.45; }
    .vorfuehrung-ueberblick { display: none; }
    #vorfuehrung-wechsel { top: 26px; left: 404px; }
  }
  @media print {  html.vorfuehrung-hand body { padding-left: 0; } #vorfuehrung-streifen { position: static; } }
